using System;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using System.Windows.Media;
using SplifyWin;
namespace Mcrf.Wpf {
 public sealed partial class MainWindow {
  Action refreshServer;
  static Brush Globe(){var group=new DrawingGroup();using(var dc=group.Open()){var pen=new Pen(Brush("#286ACDE1"),1);dc.DrawEllipse(null,pen,new Point(100,100),82,82);dc.DrawEllipse(null,pen,new Point(100,100),38,82);dc.DrawEllipse(null,pen,new Point(100,100),70,82);dc.DrawEllipse(null,pen,new Point(100,100),82,32);dc.DrawEllipse(null,pen,new Point(100,100),82,62);dc.DrawLine(pen,new Point(18,100),new Point(182,100));dc.DrawLine(pen,new Point(100,18),new Point(100,182));}group.Freeze();var brush=new DrawingBrush(group){Stretch=Stretch.Uniform};brush.Freeze();return brush;}
  StackPanel ServerControls(){
   var panel=new StackPanel{VerticalAlignment=VerticalAlignment.Center};panel.Children.Add(new Border{Background=Globe(),Height=62,Margin=new Thickness(0,0,0,10)});var top=Text("ТЕКУЩИЙ СЕРВЕР VPN",12);top.TextAlignment=TextAlignment.Center;panel.Children.Add(top);
   var name=new TextBlock{FontSize=18,FontWeight=FontWeights.SemiBold,TextAlignment=TextAlignment.Center,TextTrimming=TextTrimming.CharacterEllipsis,Margin=new Thickness(0,0,0,4)};var flag=new Image{Width=28,Height=18,Margin=new Thickness(0,0,6,0)};var row=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Center};row.Children.Add(flag);row.Children.Add(name);panel.Children.Add(row);var protocol=Text("",12);protocol.TextAlignment=TextAlignment.Center;panel.Children.Add(protocol);var latency=Text("—",21);latency.Foreground=Brush("#6BFAD8");latency.TextAlignment=TextAlignment.Center;panel.Children.Add(latency);
   var fastestPanel=new UniformGrid{Rows=1,Columns=3,Margin=new Thickness(0,6,0,10)};fastestPanel.Name="homeFastestServers";panel.Children.Add(fastestPanel);
   var auto=Neon("Автовыбор · вкл","#6BFAD8",async()=>{await session.ChangeConfiguration(()=>{if(!session.State.AutoSelect){session.State.AutoSelect=true;session.State.AutoSelectMode="first";}else if(session.State.AutoSelectMode=="first")session.State.AutoSelectMode="fast";else session.State.AutoSelect=false;});if(refreshServer!=null)refreshServer();});auto.Name="homeAutoToggle";var mode=Neon("Режим TUN","#4EE7FC",async()=>{await session.ChangeConfiguration(()=>session.State.Mode=session.State.Mode=="tun"?"proxy":"tun");if(refreshServer!=null)refreshServer();});mode.Name="homeModeToggle";panel.Children.Add(auto);panel.Children.Add(mode);
   name.MaxWidth=220;panel.SizeChanged+=(s,e)=>name.MaxWidth=Math.Max(80,panel.ActualWidth-50);string signature=null;refreshServer=()=>{
    string id=session.Core.Running&&!String.IsNullOrEmpty(session.Core.ActiveServerId)?session.Core.ActiveServerId:session.State.SelectedServerId;var node=session.State.Servers.FirstOrDefault(n=>n.Id==id);if(node==null&&session.State.AutoSelect)node=session.State.Servers.Where(n=>!WarpPicker.IsWarp(n)).OrderBy(n=>n.Latency<0?Int32.MaxValue:n.Latency).FirstOrDefault();name.Text=node==null?"Сервер не выбран":ServerIdentity.Display(node.Name);flag.Source=node==null?null:FlagImage(node.Name);protocol.Text=node==null?"Добавьте сервер или подписку":node.TransportLabel;latency.Text=node==null||node.Latency<0?"Задержка: не проверена":node.Latency+" мс";auto.Content=!session.State.AutoSelect?"Автовыбор выкл":session.State.AutoSelectMode=="first"?"Автовыбор первого":"Автовыбор быстрого";auto.BorderBrush=Brush(session.State.AutoSelect?"#6BFAD8":"#FF8CA1");auto.Foreground=auto.BorderBrush;mode.Content=session.State.Mode=="tun"?"Режим TUN":"Локальный прокси";
    var fastest=session.State.Servers.Where(n=>!WarpPicker.IsWarp(n)&&n.Latency>=0&&session.Core.HasEngine(n)).OrderBy(n=>n.Latency).Take(3).ToArray();string next=String.Join("|",fastest.Select(n=>n.Id+":"+n.Latency));if(next!=signature){fastestPanel.Children.Clear();foreach(var server in fastest){var target=server;var content=new StackPanel{Margin=new Thickness(3)};content.Children.Add(new Image{Source=FlagImage(server.Name),Width=24,Height=16,Margin=new Thickness(0,0,0,4)});content.Children.Add(new TextBlock{Text=ServerIdentity.Display(server.Name),TextTrimming=TextTrimming.CharacterEllipsis,TextAlignment=TextAlignment.Center,FontSize=11});content.Children.Add(new TextBlock{Text=server.Latency+" мс",Foreground=Brush("#6BFAD8"),TextAlignment=TextAlignment.Center,FontSize=11});var pick=AsyncButton("",()=>session.ChangeConfiguration(()=>{session.State.AutoSelect=false;session.State.SelectedServerId=target.Id;}));pick.Name="quickServer"+fastestPanel.Children.Count;pick.Content=content;pick.ToolTip=server.Name+" · "+server.TransportLabel;pick.Padding=new Thickness(2,6,2,6);pick.Margin=new Thickness(0,0,5,0);fastestPanel.Children.Add(pick);}signature=next;}
   };refreshServer();return panel;
  }
 }
}
